import React, { useState, useEffect, useRef } from 'react';
import { Tree } from 'primereact/tree';
import { NodeService } from './service/NodeService';
import { Toast } from 'primereact/toast';

export default function Events() {
    const [nodes, setNodes] = useState([]);
    const [selectedNodeKey, setSelectedNodeKey] = useState('');
    const toast = useRef(null);
    
    useEffect(() => {
        NodeService.getTreeNodes().then((data) => setNodes(data));
    }, []);

    const onExpand = (event) => {
        toast.current.show({ className: 'success', summary: 'Node Expanded', detail: event.node.label });
    };

    const onCollapse = (event) => {
        toast.current.show({ className: 'warn', summary: 'Node Collapsed', detail: event.node.label });
    };

    const onSelect = (event) => {
        toast.current.show({ className: 'info', summary: 'Node Selected', detail: event.node.label });
    };

    const onUnselect = (event) => {
        toast.current.show({ className: 'warn', summary: 'Node Unselected', detail: event.node.label });
    };

    return (
        <>
            <Toast ref={toast} />
            <div className="fvc fhc">
                <Tree value={nodes} selectionMode="single" selectionKeys={selectedNodeKey} onSelectionChange={(e) => setSelectedNodeKey(e.value)} 
                    onExpand={onExpand} onCollapse={onCollapse} onSelect={onSelect} onUnselect={onUnselect} className="w-full w300" />
            </div>
        </>
    )

}